void recomputeLUT()
    {
      auto gainLUT_ptr = gainLUT.data();

      for (gsl::index i = 0; i < LUTsize; i += 16)
      {
        if (resetRequest)
        {
          i = 0;
          resetRequest = false;
          gainLUT_ptr = gainLUT.data();
        }
        for (gsl::index j = 0; j < 16; ++j)
        {
          *(gainLUT_ptr++) = computeGain(static_cast<DataType>(i + j) / LUTprecision);
        }
      }
      isRunning = false;
    }

