            }

            sections[stageOrder].setCoefs (bCoefs, aCoefs);
        };

        calcCoefsForQ (butterQs[0] * qVal * juce::MathConstants<NumericType>::sqrt2, 0);
        for (size_t i = 1; i < NFilters; ++i)
            calcCoefsForQ (butterQs[i], i);
