            std::fill (oneFilterCoeffs.begin(), oneFilterCoeffs.end(), T {});
            for (size_t j = 0; j < coeffsPerFilter; ++j)
            {
                const auto index = (size_t) i + j * (size_t) decimationFactor;
                oneFilterCoeffs[j] = index >= coeffs.size() ? T {} : coeffs[index];
            }
