void Keyboard(unsigned char key)
    {
        switch (key)
        {
        case 'a':
            m_spring1->SetMotorSpeed(m_speed);
            break;

        case 's':
            m_spring1->SetMotorSpeed(0.0f);
            break;

        case 'd':
            m_spring1->SetMotorSpeed(-m_speed);
            break;

        case 'q':
            m_hz = b2Max(0.0f, m_hz - 1.0f);
            m_spring1->SetSpringFrequencyHz(m_hz);
            m_spring2->SetSpringFrequencyHz(m_hz);
            break;

        case 'e':
            m_hz += 1.0f;
            m_spring1->SetSpringFrequencyHz(m_hz);
            m_spring2->SetSpringFrequencyHz(m_hz);
            break;
        }
    }

