void CreateLeg(float32 s, const b2Vec2& wheelAnchor)
    {
        b2Vec2 p1(5.4f * s, -6.1f);
        b2Vec2 p2(7.2f * s, -1.2f);
        b2Vec2 p3(4.3f * s, -1.9f);
        b2Vec2 p4(3.1f * s, 0.8f);
        b2Vec2 p5(6.0f * s, 1.5f);
        b2Vec2 p6(2.5f * s, 3.7f);

        b2FixtureDef fd1, fd2;
        fd1.filter.groupIndex = -1;
        fd2.filter.groupIndex = -1;
        fd1.density = 1.0f;
        fd2.density = 1.0f;

        b2PolygonShape poly1, poly2;

        if (s > 0.0f)
        {
            b2Vec2 vertices[3];

            vertices[0] = p1;
            vertices[1] = p2;
            vertices[2] = p3;
            poly1.Set(vertices, 3);

            vertices[0] = b2Vec2_zero;
            vertices[1] = p5 - p4;
            vertices[2] = p6 - p4;
            poly2.Set(vertices, 3);
        }
        else
        {
            b2Vec2 vertices[3];

            vertices[0] = p1;
            vertices[1] = p3;
            vertices[2] = p2;
            poly1.Set(vertices, 3);

            vertices[0] = b2Vec2_zero;
            vertices[1] = p6 - p4;
            vertices[2] = p5 - p4;
            poly2.Set(vertices, 3);
        }

        fd1.shape = &poly1;
        fd2.shape = &poly2;

        b2BodyDef bd1, bd2;
        bd1.type = b2_dynamicBody;
        bd2.type = b2_dynamicBody;
        bd1.position = m_offset;
        bd2.position = p4 + m_offset;

        bd1.angularDamping = 10.0f;
        bd2.angularDamping = 10.0f;

        b2Body* body1 = m_world->CreateBody(&bd1);
        b2Body* body2 = m_world->CreateBody(&bd2);

        body1->CreateFixture(&fd1);
        body2->CreateFixture(&fd2);

        b2DistanceJointDef djd;

        // Using a soft distance constraint can reduce some jitter.
        // It also makes the structure seem a bit more fluid by
        // acting like a suspension system.
        djd.dampingRatio = 0.5f;
        djd.frequencyHz = 10.0f;

        djd.Initialize(body1, body2, p2 + m_offset, p5 + m_offset);
        m_world->CreateJoint(&djd);

        djd.Initialize(body1, body2, p3 + m_offset, p4 + m_offset);
        m_world->CreateJoint(&djd);

        djd.Initialize(body1, m_wheel, p3 + m_offset, wheelAnchor + m_offset);
        m_world->CreateJoint(&djd);

        djd.Initialize(body2, m_wheel, p6 + m_offset, wheelAnchor + m_offset);
        m_world->CreateJoint(&djd);

        b2RevoluteJointDef rjd;

        rjd.Initialize(body2, m_chassis, p4 + m_offset);
        m_world->CreateJoint(&rjd);
    }

