static void iterateAudioBuffer (AudioBuffer<float>& ab, UnaryFunction fn)
    {
        float* const* sampleData = ab.getArrayOfWritePointers();

        for (int c = ab.getNumChannels(); --c >= 0;)
            for (int s = ab.getNumSamples(); --s >= 0;)
                fn (sampleData[c][s]);
    }

