inline double	GainToDB(double aGain)
{
	if (aGain == 0.0)
		return kNeg144DB;
	else
	{
		double	dB;

		dB = log10(aGain) * 20.0;

		if (dB < kNeg144DB)
			dB = kNeg144DB;
		return (dB);		// convert factor to dB
	}
}

