// This implements `setLookAhead` — a C++ DSP routine for set look ahead.

inline int NumberOfBitsNeeded(int PowerOfTwo)
{
	int i;

	if (PowerOfTwo < 2) {
		fprintf(stderr, "Error: FFT called with size %d\n", PowerOfTwo);
		exit(1);
	}

	for (i = 0;; i++)
		if (PowerOfTwo & (1 << i))
			return i;
