float generate(){
    if(gateTime == 0){
      stage = kAttack;
      if(trig == kTrigger){
	gateState = false;
      }
    }
    if(gateTime >= 0){
      gateTime--; // this will stop at -1
    }
    switch (stage) {
    case kAttack:
      // attack ramp
      level = increment(level, attackIncrement);
      if(level >= 1.0){
	level = 1.0;
	stage = kDecay;
      }else if(gateState == false && trig == kGate){
	stage = kRelease;
      }
      break;
    case kDecay:
      // decay ramp
      level = decrement(level, decayIncrement);
      if(level <= sustain){
	level = sustain;
	if(trig == kGate){
	  stage = kSustain;
	} else { // (trig == kTrigger)
	  stage = kRelease;
	}
      } else if(gateState == false && trig == kGate){
	stage = kRelease;
      }
      break;
    case kSustain:
      level = sustain;
      if(gateState == false){
	stage = kRelease;
      }
      break;
    case kRelease:
      // release ramp
      level = decrement(level, releaseIncrement);
      if(level <= MINLEVEL){
	level = MINLEVEL;
	if (retrigger == true)
	  trigger();
	else // (retrigger == false)
	  stage = kIdle;
      }else if(gateState == true ){ // if during release the gate is on again, start over from the current level
	stage = kAttack;
      }
      break;
    case kIdle:
      level = MINLEVEL;
      if(gateState == true)
	stage = kAttack;
      break;
    }
    return level;
  }

