constexpr float db2a(float db)
   {
      if (db < 0)
         return 1.0f / db2a(-db);

      if (db < 120.0f)
      {
         auto db_10 = db * 10.0f;
         auto index = std::uint32_t(db_10);
         auto v1 = inv_db_table[index];
         auto v2 = inv_db_table[index + 1];
         return linear_interpolate(v1, v2, db_10 - index);
      }
      return 1000000.0f;
   }

