static inline float chowProcess(float x, const float threshGain, const float ratio, const bool flip)
{
    float y = x;

    if (!flip && x > threshGain)
    {
        y = threshGain;
        y += (x - threshGain) / ratio;
    }
    else if (flip && x < -threshGain)
    {
        y = -threshGain;
        y += (x + threshGain) / ratio;
    }

    return y;
}

