        using namespace chowdsp::WDF_SSE;
        constexpr float alpha = 0.4;

        S2.port1 = std::make_unique<Resistor>(2.7e3f); // Rgk

        auto &P3 = S2.port2;
        auto &I1 = P3->port1;
        I1->port1 = std::make_unique<ResistiveVoltageSource>(); // Vin
        Vin = I1->port1.get();

        auto &P2 = P3->port2;
