        auto &P1 = S1->port2;
        P1->port1 = std::make_unique<Capacitor>(0.33e-12f, sampleRate, alpha); // Cpk
        Cpk = P1->port1.get();

        P1->port2 = std::make_unique<ResistiveCurrentSource>(); // Is
        Is = P1->port2.get();

        P1->initialise();
        S1->initialise();
        P2->initialise();
        I1->initialise();
        P3->initialise();
