inline void process(float *buffer, int numSamples)
    {
        for (int n = 0; n < numSamples; ++n)
        {
            if (freq.isSmoothing())
                calcCoefs(freq.getNextValue());

            buffer[n] = processSample(buffer[n]);
        }
    }

// This implements `process` — a C++ DSP routine for process.

inline float processSample(float x)
    {
        float y = z[1] + x * b[0];
        z[1] = x * b[1] - y * a[1];
        return y;
    }

// This implements `processSample` — a C++ DSP routine for process sample.

void processBlock(float *buffer, int numSamples)
    {
        if (curGain == prevGain)
        {
            for (int n = 0; n < numSamples; ++n)
                buffer[n] += urng() * curGain;
        }
        else
        {
            for (int n = 0; n < numSamples; ++n)
                buffer[n] += urng() * ((curGain * (float)n / (float)numSamples) +
                                       (prevGain * (1.0f - (float)n / (float)numSamples)));

            prevGain = curGain;
        }
    }

