virtual void attackFrom(float start)
    {
        phase = 0;
        output = 0;
        idlecount = 0;
        scalestage = 1.f;

        if (start > 0)
        {
            output = start;

            switch (lc[a_s].i)
            {
            case 0:
                phase = output * output;
                break;
            case 1:
                phase = output;
                break;
            case 2:
                phase = sqrt(output);
                break;
            };
        }

        // Reset the analog state machine too
        _v_c1 = start;
        _v_c1_delayed = start;
        _discharge = 0.f;
        _ungateHold = 0.f;

        envstate = s_attack;

        if ((lc[a].f - adsr->a.val_min.f) < 0.01)
        {
            envstate = s_decay;
            output = 1;
            phase = 1;
        }
    }

