void populateDatum(Datum &d, const SurgeSynthesizer *synth)
    {
        std::string sceneMod = "";
        d.isPerScene = synth->isModulatorDistinctPerScene((modsources)d.source_id);

        if (synth->isModulatorDistinctPerScene((modsources)d.source_id))
        {
            sceneMod = std::string(" (") + (d.source_scene == 0 ? "A" : "B") + ")";
        }

        char nm[1024];
        SurgeSynthesizer::ID ptagid;
        auto p = synth->storage.getPatch().param_ptr[d.destination_id + d.idBase];
        if (p->ctrlgroup == cg_LFO)
        {
            std::string pfx = p->scene == 1 ? "A " : "B ";
            p->create_fullname(p->get_name(), nm, p->ctrlgroup, p->ctrlgroup_entry,
                               (pfx + ModulatorName::modulatorName(
                                          &synth->storage, p->ctrlgroup_entry, true, p->scene))
                                   .c_str());
        }
        else
        {
            if (synth->fromSynthSideId(d.destination_id + d.idBase, ptagid))
                synth->getParameterName(ptagid, nm);
        }
        d.pscene = p->scene;
        d.pControlGroup = p->ctrlgroup;

        std::string sname = ModulatorName::modulatorNameWithIndex(
            &synth->storage, d.source_scene, d.source_id, d.source_index, false, d.inScene < 0);

        d.sname = sname + sceneMod;
        d.pname = nm;

        char pdisp[TXT_SIZE];
        int ptag = p->id;
        auto thisms = (modsources)d.source_id;

        d.moddepth01 = synth->getModDepth01(ptag, thisms, d.source_scene, d.source_index);
        d.isBipolar = synth->isBipolarModulation(thisms);
        d.isMuted = synth->isModulationMuted(ptag, thisms, d.source_scene, d.source_index);
        p->get_display_of_modulation_depth(
            pdisp, synth->getModDepth(ptag, thisms, d.source_scene, d.source_index),
            synth->isBipolarModulation(thisms), Parameter::InfoWindow, &(d.mss));
        d.moddepth = pdisp;
    }

// This implements `populateDatum` — a C++ DSP routine for populate datum.

void rebuildFrom(SurgeSynthesizer *synth)
    {
        removeAllChildren();
        dataRows.clear();
        rows.clear();
        int ypos = 0;
        auto append = [this, synth](const std::string &type,
                                    const std::vector<ModulationRouting> &r, int idBase,
                                    int scene) {
            if (r.empty())
                return;

            for (const auto &q : r)
            {
                Datum d;
                d.source_scene = q.source_scene;
                d.source_id = q.source_id;
                d.source_index = q.source_index;
                d.destination_id = q.destination_id;
                d.idBase = idBase;
                d.inScene = scene;
                populateDatum(d, synth);
                dataRows.push_back(d);
            }
        };

        {
            std::lock_guard<std::recursive_mutex> modLock(synth->storage.modRoutingMutex);

            // FIXME mutex lock
            append("Global Modulators", synth->storage.getPatch().modulation_global, 0, -1);
            append("Scene A - Voice Modulators",
                   synth->storage.getPatch().scene[0].modulation_voice,
                   synth->storage.getPatch().scene_start[0], 0);
            append("Scene A - Scene Modulators",
                   synth->storage.getPatch().scene[0].modulation_scene,
                   synth->storage.getPatch().scene_start[0], 0);
            append("Scene B - Voice Modulators",
                   synth->storage.getPatch().scene[1].modulation_voice,
                   synth->storage.getPatch().scene_start[1], 1);
            append("Scene B - Scene Modulators",
                   synth->storage.getPatch().scene[1].modulation_scene,
                   synth->storage.getPatch().scene_start[1], 1);
        }

        std::sort(dataRows.begin(), dataRows.end(), [this](const Datum &a, const Datum &b) -> bool {
            if (sortOrder == BY_SOURCE)
            {
                if (a.isPerScene && b.isPerScene)
                    if (a.source_scene != b.source_scene)
                        return a.source_scene < b.source_scene;

                if (a.source_id != b.source_id)
                    return a.source_id < b.source_id;

                if (a.source_index != b.source_index)
                    return a.source_index < b.source_index;

                if (a.destination_id != b.destination_id)
                    return a.destination_id < b.destination_id;
            }
            else
            {
                if (a.destination_id != b.destination_id)
                    return a.destination_id < b.destination_id;

                if (a.isPerScene && b.isPerScene)
                    if (a.source_scene != b.source_scene)
                        return a.source_scene < b.source_scene;

                if (a.source_id != b.source_id)
                    return a.source_id < b.source_id;

                if (a.source_index != b.source_index)
                    return a.source_index < b.source_index;
            }

            return false;
        });

        std::string priorN = "-";

        int idx = 0;
        for (const auto &d : dataRows)
        {
            auto included = filterOn == NONE || (filterOn == SOURCE && d.sname == filterString) ||
                            (filterOn == TARGET && d.pname == filterString) ||
                            (filterOn == TARGET_CG && d.pControlGroup == filterInt) ||
                            (filterOn == TARGET_SCENE && d.pscene == filterInt);

            if (!included)
            {
                continue;
            }
            auto l = std::make_unique<DataRowEditor>(d, idx++, this);
            auto sortName = sortOrder == BY_SOURCE ? d.sname : d.pname;

            l->setSkin(skin, associatedBitmapStore);

            if (sortName != priorN)
            {
                priorN = sortName;
                l->firstInSort = true;
            }

            if (included)
            {
                l->setBounds(0, ypos, getWidth(), DataRowEditor::height);
                ypos += DataRowEditor::height;
                addAndMakeVisible(*l);
            }

            l->hasFollower = false;
            rows.push_back(std::move(l));
        }

        // this is a bit gross but i can't think of a better way
        for (int i = 1; i < rows.size(); ++i)
        {
            auto sni = sortOrder == BY_SOURCE ? rows[i]->datum.sname : rows[i]->datum.pname;
            auto snm = sortOrder == BY_SOURCE ? rows[i - 1]->datum.sname : rows[i - 1]->datum.pname;
            if (sni == snm)
                rows[i - 1]->hasFollower = true;
        }

        if (!rows.empty())
        {
            rows.back()->isLast = true;
        }

        bool needVSB = true;
        int sbw = 10;

        if (editor && editor->viewport && editor->viewport->getHeight() > 0)
        {
            if (ypos > editor->viewport->getHeight())
            {
                needVSB = true;
            }
            else
            {
                needVSB = false;
            }
            sbw = editor->viewport->getScrollBarThickness() + 2;
            editor->viewport->setScrollBarsShown(sbw, false);

            if (rows.empty())
            {
                ypos = editor->viewport->getHeight();
            }
        }

        auto w = viewportWidth - (needVSB ? sbw : 0) - 3;

        setSize(w, ypos);

        for (const auto &r : rows)
        {
            auto b = r->getBounds().withWidth(w - 1);
            r->setBounds(b);
        }

        moved(); // to refresh the 'istop'

        if (preferredFocusRow < 0 || preferredFocusRow >= dataRows.size())
            preferredFocusRow = 0;

        if (preferredFocusRow >= 0 && preferredFocusRow < rows.size() && rows[preferredFocusRow])
            rows[preferredFocusRow]->beTheFocusedRow();
    }

// This implements `rebuildFrom` — a C++ DSP routine for rebuild from.

inline void drawAxis(juce::Graphics &g)
    {
        auto primaryFont = skin->fontManager->getLatoAtSize(9, juce::Font::bold);
        auto secondaryFont = skin->fontManager->getLatoAtSize(7);

        auto haxisArea = getHAxisArea();
        auto tpx = timeToPx();
        float maxt = drawDuration();

        // draw loop area
        if (ms->loopMode != MSEGStorage::ONESHOT && ms->editMode != MSEGStorage::LFO)
        {
            int ls = (ms->loop_start >= 0 ? ms->loop_start : 0);
            int le = (ms->loop_end >= 0 ? ms->loop_end : ms->n_activeSegments - 1);

            float pxs = limit_range((float)tpx(ms->segmentStart[ls]), (float)haxisArea.getX(),
                                    (float)haxisArea.getRight());
            float pxe = limit_range((float)tpx(ms->segmentEnd[le]), (float)haxisArea.getX(),
                                    (float)haxisArea.getRight());

            auto r = juce::Rectangle<float>(juce::Point<float>(pxs, haxisArea.getY()),
                                            juce::Point<float>(pxe, haxisArea.getY() + 15));

            // draw the loop region start to end
            if (!(ms->loop_start == ms->loop_end + 1))
            {
                g.setColour(skin->getColor(Colors::MSEGEditor::Loop::RegionAxis));
                g.fillRect(r);
            }

            auto mcolor = skin->getColor(Colors::MSEGEditor::Loop::Marker);

            // draw loop markers
            if ((loopDragTime < 0 || !loopDragIsStart) && (ls >= 0 && ls < ms->segmentStart.size()))
            {
                drawLoopDragMarker(g, mcolor, hotzone::LOOP_START, ms->segmentStart[ls]);
            }

            if ((loopDragTime < 0 || loopDragIsStart) && (le >= 0 && le < ms->segmentStart.size()))
            {
                drawLoopDragMarker(g, mcolor, hotzone::LOOP_END, ms->segmentEnd[le]);
            }

            // loop marker when dragged
            if (loopDragTime >= 0)
            {
                drawLoopDragMarker(g, mcolor,
                                   (loopDragIsStart ? hotzone::LOOP_START : hotzone::LOOP_END),
                                   loopDragTime);
            }
        }

        updateHTicks();

        for (auto hp : hTicks)
        {
            float t = hp.first;
            auto c = hp.second;
            float px = tpx(t);
            int yofs = 13;
            std::string txt;

            if (!(c & TickDrawStyle::kNoLabel))
            {

                int sw = 0;

                if (fmod(t, 1.f) == 0.f)
                {
                    g.setColour(skin->getColor(Colors::MSEGEditor::Axis::Text));
                    g.setFont(primaryFont);
                    txt = fmt::format("{:d}", int(t));
                    sw = SST_STRING_WIDTH_INT(primaryFont, txt);
                }
                else
                {
                    g.setColour(skin->getColor(Colors::MSEGEditor::Axis::SecondaryText));
                    g.setFont(secondaryFont);
                    txt = fmt::format("{:5.2f}", t);
                    sw = SST_STRING_WIDTH_INT(secondaryFont, txt);
                }

                g.drawText(txt, px - (sw / 2), haxisArea.getY() + 2, sw, yofs,
                           juce::Justification::centredBottom);
            }
        }

        // vertical axis
        auto vaxisArea = getVAxisArea();
        auto valpx = valToPx();

        vaxisArea = vaxisArea.expanded(1, 0);

        g.setColour(skin->getColor(Colors::MSEGEditor::Axis::Line));
        auto s = vaxisArea.getTopRight();
        auto b = vaxisArea.getBottomRight().translated(0, 4);
        g.drawLine(s.getX(), s.getY(), b.getX(), b.getY(), 1);

        g.setFont(primaryFont);
        g.setColour(skin->getColor(Colors::MSEGEditor::Axis::Text));

        updateVTicks();

        auto uni = lfodata->unipolar.val.b;

        for (auto vp : vTicks)
        {
            float p = valpx(std::get<0>(vp));

            float off = vaxisArea.getWidth() * 0.666;

            if (std::get<2>(vp))
            {
                off = 0;
            }

            if (off == 0)
            {
                g.setColour(skin->getColor(Colors::MSEGEditor::Axis::Line));
            }
            else
            {
                g.setColour(skin->getColor(Colors::MSEGEditor::Grid::SecondaryHorizontal));
                g.drawLine(vaxisArea.getX() + off, p, vaxisArea.getRight() - 1.f, p);
            }

            if (off == 0)
            {
                std::string txt;
                auto value = std::get<1>(vp);
                int ypos = 3;

                if (value == 0.f && std::signbit(value))
                {
                    value = -value;
                }

                txt = fmt::format("{:5.1f}", value);

                g.setColour(skin->getColor(Colors::MSEGEditor::Axis::SecondaryText));

                if (value == 1.f)
                {
                    g.drawText(txt, vaxisArea.getX() - 3, p, vaxisArea.getWidth(), 12,
                               juce::Justification::topRight);
                }
                else if (value == -1.f || (value == 0.f && uni))
                {
                    g.drawText(txt, vaxisArea.getX() - 3, p - 12, vaxisArea.getWidth(), 12,
                               juce::Justification::bottomRight);
                }
                else
                {
                    g.drawText(txt, vaxisArea.getX() - 3, p - 6, vaxisArea.getWidth(), 12,
                               juce::Justification::centredRight);
                }
            }
        }
    }

// This implements `drawAxis` — a C++ DSP routine for draw axis.

void updateVTicks()
    {
        auto uni = lfodata->unipolar.val.b;

        if (ms->vSnapDefault != vTickAsOf)
        {
            vTicks.clear();

            float dStep = ms->vSnapDefault;
            // See comment above
            if (dStep <= 0)
            {
                dStep = 0.01;
            }

            while (dStep < 1.0 / (gridMaxVSteps * (1 + uni)))
            {
                dStep *= 2;
            }

            int steps = ceil(1.0 / dStep);
            int start, end;

            if (uni)
            {
                start = 0;
                end = steps + 1;
            }
            else
            {
                start = -steps - 1;
                end = steps + 1;
            }

            for (int vi = start; vi < end; vi++)
            {
                float val = vi * dStep;
                auto doDraw = true;

                if (val > 1)
                {
                    val = 1.0;
                    if (vi != end - 1)
                        doDraw = false;
                }

                if (val < -1)
                {
                    val = -1.0;
                    if (vi != start)
                        doDraw = false;
                }

                if (uni && val < 0)
                {
                    val = 0;
                    if (vi != start)
                        doDraw = false;
                }

                if (doDraw)
                {
                    // Little secret: unipolar is just a relabeled bipolar
                    float pval = val;

                    if (uni)
                    {
                        pval = val * 2 - 1;
                    }

                    vTicks.push_back(
                        std::make_tuple(pval, val, vi == 0 || vi == start || vi == end - 1));
                }
            }
        }
    }

